<?php elseif($tab==='images'): ?><section class="panel"><h2>بارگذاری و تطبیق تصاویر</h2><p>ابتدا شهید ثبت شود. نام فایل مانند <b dir="ltr">001254-1.jpg</b> باشد. حداکثر ۱۰ فایل در هر نوبت؛ فایل‌های اصلی تغییر نمی‌کنند.</p><form method="post" enctype="multipart/form-data" action="<?= e(url('admin',['tab'=>'images'])) ?>" data-upload-form data-max-files="10"><?= Security::field() ?><input type="hidden" name="action" value="images"><div class="fields"><?php foreach(['title'=>'عنوان (اختیاری)','designer'=>'طراح','license_text'=>'شرایط استفاده'] as $k=>$label): ?><div class="field"><label for="<?= $k ?>"><?= $label ?></label><input id="<?= $k ?>" name="<?= $k ?>"></div><?php endforeach ?><div class="field"><label for="kind">نوع</label><select name="kind" id="kind"><option value="design">تصویر طراحی‌شده</option><option value="photo">عکس اصلی</option><option value="document">سند تصویری</option></select></div><div class="field full"><label for="images">فایل‌ها</label><input id="images" type="file" name="images[]" multiple required accept=".jpeg,.jpg,.png,.webp,image/jpeg,image/png,image/webp" aria-describedby="image-formats"></div></div><p class="hint" id="image-formats">فرمت‌های مجاز: JPEG، JPG، PNG و WebP. حداکثر ۱۰ فایل در هر نوبت. درصد و حجم باقی‌مانده هنگام ارسال نمایش داده می‌شود.</p><?php view('upload-status'); ?><button class="primary">بارگذاری</button></form></section><section class="panel tablewrap"><table><tr><th>عنوان</th><th>شهید</th><th>انتشار</th></tr><?php foreach(Db::query($db,'SELECT i.*,m.code FROM images i JOIN martyrs m ON m.id=i.martyr_id ORDER BY i.id DESC LIMIT 100')->fetchAll() as $im): ?><tr><td><?= e($im['title']) ?></td><td><?= e($im['code']) ?></td><td><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="image-publish"><input type="hidden" name="id" value="<?= $im['id'] ?>"><input type="hidden" name="published" value="<?= $im['published']?0:1 ?>"><button class="outline"><?= $im['published']?'توقف انتشار':'انتشار' ?></button></form></td></tr><?php endforeach ?></table></section>
<?php elseif($tab==='categories'): ?><section class="panel"><h2>دسته‌بندی‌ها</h2><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="category"><div class="field"><label for="name">عنوان دسته جدید</label><input id="name" name="name" required></div><button class="primary">افزودن</button></form><ul><?php foreach(Db::query($db,'SELECT * FROM categories ORDER BY name')->fetchAll() as $c): ?><li><?= e($c['name']) ?></li><?php endforeach ?></ul></section>
<?php elseif($tab==='import'): ?><section class="panel"><h2>ورود Excel</h2><p>فایل XLSX با ستون‌های <b dir="ltr">code, first_name, last_name</b>؛ ستون کد حتماً Text باشد. رکورد موجود حفظ می‌شود و بازنویسی خودکار نداریم.</p><form method="post" enctype="multipart/form-data"><?= Security::field() ?><input type="hidden" name="action" value="import-preview"><div class="field"><label for="excel">فایل XLSX</label><input id="excel" type="file" name="excel" required accept=".xlsx"></div><button class="primary">پیش‌نمایش و اعتبارسنجی</button></form><?php if(isset($_SESSION['import_rows'])): ?><?php $rows=Namira\Importer::preview($db,$_SESSION['import_rows']); ?><p><?= fa(count($rows)) ?> ردیف (نمایش ۱۰۰ ردیف اول)</p><div class="tablewrap"><table><tr><th>ردیف</th><th>کد</th><th>نام</th><th>وضعیت</th></tr><?php foreach(array_slice($rows,0,100) as $r): ?><tr><td><?= $r['row'] ?></td><td><?= e($r['code']) ?></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><?= e($r['status'].' '.$r['error']) ?></td></tr><?php endforeach ?></table></div><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="import-commit"><p><button class="primary">تأیید ورود ردیف‌های معتبر و جدید</button></p></form><?php endif ?><?php if(isset($_SESSION['import_result'])): ?><pre><?= e(json_encode($_SESSION['import_result'],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)) ?></pre><?php endif ?></section><section class="panel"><h2>خروجی XLSX واقعی</h2><p>همان فیلترهای نام، استان، شهر، شغل، سازمان و دسته آرشیو قابل اعمال‌اند. هر شهید و تصویر در شیت جدا قرار می‌گیرند.</p><form method="get" action="/index.php"><input type="hidden" name="page" value="export"><div class="fields"><?php foreach(['q'=>'نام یا کد','province'=>'استان','city'=>'شهر','job'=>'شغل','organization'=>'سازمان'] as $key=>$label): ?><div class="field"><label for="export_<?= $key ?>"><?= $label ?></label><input id="export_<?= $key ?>" name="<?= $key ?>"></div><?php endforeach ?></div><button class="outline">دریافت Excel</button></form></section>
<?php elseif($tab==='requests'): ?><section class="panel tablewrap"><h2>درخواست‌های طراحی</h2><table><tr><th>شهید</th><th>متقاضی</th><th>تصاویر اولیه</th><th>وضعیت</th></tr><?php foreach(Db::query($db,'SELECT * FROM design_requests ORDER BY id DESC LIMIT 100')->fetchAll() as $r): ?><tr><td><?= e($r['martyr_name']) ?><p><?= e($r['notes']) ?></p></td><td><?= e($r['requester']) ?><br><?= e($r['phone']) ?></td><td><?php foreach(Db::query($db,'SELECT id FROM request_files WHERE request_id=?',[$r['id']])->fetchAll() as $f): ?><a class="outline" href="<?= e(url('request-file',['id'=>$f['id']])) ?>">دریافت عکس</a><?php endforeach ?></td><td><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="request-status"><input type="hidden" name="id" value="<?= $r['id'] ?>"><select name="status" aria-label="وضعیت درخواست"><?php foreach(['submitted'=>'ثبت‌شده','reviewing'=>'بررسی','accepted'=>'پذیرفته','completed'=>'انجام‌شده','rejected'=>'رد یا اصلاح'] as $s=>$label): ?><option value="<?= $s ?>" <?= $r['status']===$s?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button class="outline">ذخیره</button></form></td></tr><?php endforeach ?></table></section>
<?php elseif($tab==='products'): ?><section class="panel"><h2>ثبت محصول و تنوع اول</h2><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="product"><div class="fields"><?php foreach(['title'=>'عنوان','category'=>'دسته','sku'=>'SKU یکتا','attributes'=>'تنوع: اندازه، رنگ، جنس و قاب','price'=>'قیمت (تومان)','stock'=>'موجودی','image_id'=>'شناسه تصویر آرشیو (اختیاری)'] as $key=>$label): ?><div class="field"><label for="<?= $key ?>"><?= $label ?></label><input name="<?= $key ?>" id="<?= $key ?>" <?= $key!=='image_id'?'required':'' ?> <?= in_array($key,['price','stock','image_id'])?'type="number" min="0"':'' ?>></div><?php endforeach ?><div class="field full"><label for="description">توضیحات</label><textarea name="description" id="description"></textarea></div></div><button class="primary">ذخیره محصول</button></form></section><section class="panel tablewrap"><table><tr><th>محصول</th><th>SKU</th><th>قیمت</th><th>موجودی</th></tr><?php foreach(Db::query($db,'SELECT v.*,p.title FROM variants v JOIN products p ON p.id=v.product_id ORDER BY p.id DESC LIMIT 100')->fetchAll() as $v): ?><tr><td><?= e($v['title'].' '.$v['attributes']) ?></td><td><?= e($v['sku']) ?></td><td><?= fa($v['price']) ?></td><td><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="stock"><input type="hidden" name="id" value="<?= $v['id'] ?>"><input aria-label="موجودی" name="stock" type="number" min="0" value="<?= $v['stock'] ?>"><button class="outline">ثبت</button></form></td></tr><?php endforeach ?></table></section>
<?php elseif($tab==='orders'): ?><section class="panel tablewrap"><h2>سفارش‌ها و ارسال دستی</h2><table><tr><th>سفارش</th><th>مشتری</th><th>مبلغ تومان</th><th>وضعیت و رهگیری</th></tr><?php foreach(Db::query($db,'SELECT * FROM orders ORDER BY id DESC LIMIT 100')->fetchAll() as $o): ?><tr><td><a class="outline" href="<?= e(url('order',['token'=>$o['token']])) ?>"><?= fa($o['id']) ?></a></td><td><?= e($o['customer']) ?></td><td><?= fa(number_format((int)$o['total'])) ?></td><td><p><?= e($o['status']) ?></p><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="order-status"><input type="hidden" name="id" value="<?= $o['id'] ?>"><select name="status" aria-label="وضعیت سفارش"><?php foreach(['preparing'=>'آماده‌سازی','shipped'=>'ارسال‌شده','delivered'=>'تحویل‌شده','cancelled'=>'لغو','returned'=>'مرجوع‌شده'] as $s=>$label): ?><option value="<?= $s ?>"><?= $label ?></option><?php endforeach ?></select><input name="tracking" aria-label="کد رهگیری" placeholder="کد رهگیری" value="<?= e($o['tracking']) ?>"><button class="outline">ثبت</button></form></td></tr><?php endforeach ?></table></section>
<?php elseif($tab==='returns'): ?><section class="panel tablewrap"><h2>درخواست مرجوعی</h2><table><tr><th>سفارش</th><th>دلیل</th><th>وضعیت</th></tr><?php foreach(Db::query($db,'SELECT * FROM return_requests ORDER BY id DESC LIMIT 100')->fetchAll() as $r): ?><tr><td><?= fa($r['order_id']) ?></td><td><?= e($r['reason']) ?></td><td><?= e($r['status']) ?></td></tr><?php endforeach ?></table></section>
<?php elseif($tab==='users'): ?><section class="panel"><h2>کاربران مدیریت</h2><p>ساخت، تغییر نقش و غیرفعال‌کردن حساب از CLI هاست انجام می‌شود؛ دستورها در README هستند.</p><div class="tablewrap"><table><tr><th>ایمیل</th><th>نقش</th><th>فعال</th></tr><?php foreach(Db::query($db,'SELECT email,role,active FROM users')->fetchAll() as $u): ?><tr><td><?= e($u['email']) ?></td><td><?= e($u['role']) ?></td><td><?= $u['active']?'بله':'خیر' ?></td></tr><?php endforeach ?></table></div></section>
